// Reads one line of `key=value` parts separated by `;` into a row. The
// fields table says how each key's text is read; a field wrapped by many()
// may appear several times and collects its values. Parts whose key the
// table does not name are kept, as written, in `skipped`.
export function many(read) {
  return { each: read };
}
export function readLine(fields, line) {
  const row = { skipped: [] };
  for (const part of line.split(";")) {
    if (part === "") continue;
    const at = part.indexOf("=");
    const key = at < 0 ? part : part.slice(0, at);
    const text = at < 0 ? "" : part.slice(at + 1);
    const field = fields[key];
    if (field === undefined) {
      row.skipped.push(part);
      continue;
    }
    if (typeof field === "function") {
      row[key] = field(text);
    } else {
      if (row[key] === undefined) row[key] = [];
      row[key].push(field.each(text));
    }
  }
  return row;
}
